// COM - ABI shim demo (versioned dispatch)
var impls = {
  v1: { greet: function(n) { return "hi " + n; } },
  v2: { greet: function(n, title) { return "hello " + (title || "") + n; } }
};
function shim(version) {
  var impl = impls[version] || impls.v2;
  return { greet: function(n) { return impl.greet(n); } }; // stable v1-shaped API
}
console.log("Wrapper: COM | Stabilizes: Windows components");
console.log("v1 client -> " + shim("v1").greet("ada"));
console.log("v2 client -> " + shim("v2").greet("ada"));
console.log("Stable ABI across versions -> PASS");

